import openpyxl,json,datetime,pathlib
root=pathlib.Path('/workspace/mu')
p='/workspace/attachments/ab1f3992-f149-4029-a6af-afb47951cb55/美容報表.xlsx'
w=openpyxl.load_workbook(p); data=[]
for s in w:
 cells={}
 for row in s:
  for c in row:
   if c.value is not None:
    v=c.value
    if isinstance(v,(datetime.datetime,datetime.date)):v=v.isoformat()[:10]
    elif isinstance(v,datetime.time):v=v.isoformat()
    cells[c.coordinate]={'value':v,'format':c.number_format}
 data.append({'name':s.title,'rows':s.max_row,'cols':s.max_column,'cells':cells,'merges':list(map(str,s.merged_cells.ranges))})
(root/'workbook.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
